<script>
  let isRunning = false;
  let intervalId = null;
  let seconds = $state(0);

  function increment() {
    if (isRunning) return;
    isRunning = true;
    intervalId = setInterval(incrementor, 1000);
  }

  function decrement() {
    if (!isRunning) return;
    if (seconds() <= 0) return;
    isRunning = false;
    clearInterval(intervalId);
    seconds = $derived(() => Math.max(0, seconds() - 1));
  }

  function reset() {
    if (isRunning) {
      isRunning = false;
      clearInterval(intervalId);
    }
    seconds = 0;
  }

  function incrementor() {
    seconds += 1;
  }
</script>

<div class="stopwatch">
  <span class="label">Elapsed</span>
  <span class="value">{seconds()}s</span>
  <div class="buttons">
    {#if isRunning}
      <button class="btn btn-sm btn-secondary" onclick={decrement}>Pause</button>
    {:else}
      <button class="btn btn-sm btn-primary" onclick={increment}>Start</button>
    {/if}
    <button class="btn btn-sm btn-clear" onclick={reset}>Reset</button>
  </div>
</div>

